-- PT115-S4-Q24. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT115-S4-Q24$batch09$ AND q.stimulus=$batch09$A park’s user fees are employed to maintain the park. When fewer people use the park, it suffers less wear. Thus raising user fees improves park maintenance even if the number of people who stop using the park because of higher fees is great enough to reduce the revenues devoted to maintenance.$batch09$ AND q.prompt=$batch09$Which one of the following conforms most closely to the principle illustrated by the statements above?$batch09$ AND q.correct_choice=$batch09$E$batch09$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT115-S4-Q24$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT115-S4-Q24$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$Raising a park's user fees drives some people away. Fewer users means less wear, so maintenance improves. This holds even if so many people leave that the money for maintenance actually drops.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The chain is: raise the fee, lose users, less wear, better condition. The twist is in the last clause. The condition improves even though the money for upkeep goes down. Less use matters more than less money.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A fee increase that drives users away, so the thing ends up in better shape despite less money for its upkeep.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT115-S4-Q24$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Better warranties raise market share and cut profits. No fee drives users away, and nothing is wearing out less.$batch09$), ($batch09$B$batch09$, $batch09$The store closes overnight, not raising a fee, and its revenue rises. In the stimulus, revenue can fall while the condition improves.$batch09$), ($batch09$C$batch09$, $batch09$Here more money comes in, and the service still gets worse. That reverses the stimulus, where less money and better condition go together.$batch09$), ($batch09$D$batch09$, $batch09$More spending brings more visitors, and the extra revenue covers the cost. Usage goes up, not down.$batch09$), ($batch09$E$batch09$, $batch09$Library fees rise, there are fewer patrons, and the books are in better repair even though the money for repairs has dropped. Every link matches, including the twist that less money still means better condition.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT115-S4-Q24$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
